           VALUES('mata','vale_silente','Mata do Vale','Árvores altas, cipós e um silêncio que não parece natural. Entre as rochas, o vento some.',21,52,'mata',0,1,'{"tempModifier":1,"woodSource":true,"canBuildShelter":true,"examineText":"Há galhos quebrados na altura do peito, numa linha reta — alguém abriu caminho por aqui há pouco tempo.","loot":[{"itemId":"garrafa_vazia","qty":1,"base":45}]}')
           ON CONFLICT(id) DO UPDATE SET name=excluded.name, description=excluded.description, x=excluded.x, y=excluded.y,
