INSERT INTO locations(id,scenario_id,name,description,x,y,terrain,hidden_initially,danger_level,properties)
           VALUES('abrigo','vale_silente','Acampamento abandonado','Uma lona esticada sobre estacas, caixas de madeira e uma fogueira antiga.',39,41,'acampamento',0,0,'{"naturalShelter":true,"woodSource":true,"examineText":"Sob uma das caixas, um saco plástico bem dobrado, guardado com cuidado de quem pretendia voltar.","loot":[{"itemId":"caneca","qty":1,"base":60},{"itemId":"corda","qty":1,"base":55},{"itemId":"pastilhas","qty":1,"base":55,"requiresExamined":true}]}')
           ON CONFLICT(id) DO UPDATE SET name=excluded.name, description=excluded.description, x=excluded.x, y=excluded.y,
