INSERT INTO locations(id,scenario_id,name,description,x,y,terrain,hidden_initially,danger_level,properties)
           VALUES('trilha','vale_silente','Trilha da crista','Uma trilha estreita subindo pela crista norte, com marcas de tinta laranja nos troncos.',40,15,'trilha',0,1,'{"tempModifier":-1,"woodSource":true,"canBuildShelter":true,"examineText":"As marcas de tinta laranja são recentes. Seguem para leste, em direção à antena.","examineRevealsLinks":[["trilha","estacao"]],"loot":[{"itemId":"chocolate","qty":1,"base":40},{"itemId":"analgesico","qty":1,"base":45,"requiresExamined":true}]}')
           ON CONFLICT(id) DO UPDATE SET name=excluded.name, description=excluded.description, x=excluded.x, y=excluded.y,
