INSERT INTO locations(id,scenario_id,name,description,x,y,terrain,hidden_initially,danger_level,properties)
           VALUES('lago','vale_silente','Poço escuro','Um poço largo de água parada, cercado de pedras lisas. A superfície reflete a lua como um olho.',21,77,'lago',0,1,'{"tempModifier":-2,"water":"lake","examineText":"Na margem, uma pequena ponte de madeira atravessa o córrego para sudeste. Parece firme.","examineRevealsLinks":[["lago","rochedo"]],"loot":[{"itemId":"isqueiro","qty":1,"base":40,"requiresExamined":true}]}')
