INSERT INTO events(id,scenario_id,title,body,location_id,trigger,priority,repeatable) VALUES('vs_despertar','vale_silente','Silêncio depois do impacto','[exhales] O zumbido nos ouvidos é a primeira coisa que volta. Depois, o cheiro de combustível. Você está preso ao assento de um bimotor tombado entre as árvores. A cabine está aberta e vazia. [tense] O cinto do piloto não se rompeu: [pause] foi cortado. No painel, entre chiados, uma voz de mulher repete números, devagar: [whispers] “sete… quatro… zero…”','destrocos','{"start":true}',100,0)
           ON CONFLICT(id) DO UPDATE SET title=excluded.title, body=excluded.body, location_id=excluded.location_id,
             trigger=excluded.trigger, priority=excluded.priority, repeatable=excluded.repeatable;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_despertar.examinar','vs_despertar','Soltar o cinto com calma e examinar a cabine',10,'{}','{"text":"Você solta o cinto e tateia o chão da cabine.","check":{"attr":"percepcao","base":55},"success":{"text":"Uma lanterna rolou para baixo do banco. E no painel, o transmissor de emergência (ELT) está na posição OFF. [pause] [ominous] Não quebrou — alguém desligou.","effects":[{"op":"addItem","item":"lanterna"},{"op":"clue","key":"elt_desligado"}]},"failure":{"text":"Você acha uma lanterna rolando sob o banco, mas ao se soltar abre o antebraço numa borda de metal.","effects":[{"op":"addItem","item":"lanterna"},{"op":"wound","part":"braco_esq","type":"laceracao","severity":1}]}}',0,0)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_despertar.sair','vs_despertar','Sair imediatamente — o cheiro de combustível é forte',3,'{}','{"text":"Você se joga contra a janela lateral quebrada.","check":{"attr":"agilidade","base":60},"success":{"text":"Você cai na lama do lado de fora. Está vivo. O avião não pega fogo.","effects":[{"op":"status","field":"stress","delta":-5}]},"failure":{"text":"Um pedaço de fuselagem rasga sua perna ao passar pela janela.","effects":[{"op":"wound","part":"perna_dir","type":"laceracao","severity":2}]}}',0,1)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_despertar.gritar','vs_despertar','Gritar pelo piloto',3,'{}','{"text":"Sua voz some entre as árvores. Por alguns segundos, a mata inteira se cala — insetos, sapos, tudo. [long pause] [whispers] Depois, bem longe, alguém grita de volta. Não dá para saber se é resposta ou eco.","effects":[{"op":"status","field":"stress","delta":15},{"op":"flag","key":"ouviu_resposta"},{"op":"clue","key":"voz_na_mata"}]}',1,2)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO events(id,scenario_id,title,body,location_id,trigger,priority,repeatable) VALUES('vs_bagageiro','vale_silente','O compartimento de carga','[breathing heavily] A porta do bagageiro está amassada e emperrada. Pela fresta dá para ver uma mala, uma jaqueta e uma caixa com o símbolo de bateria: a fonte de emergência do avião.','destrocos','{"afterEvent":"vs_despertar","flagsNone":["bagageiro_aberto"],"cooldownMinutes":90}',50,1)
           ON CONFLICT(id) DO UPDATE SET title=excluded.title, body=excluded.body, location_id=excluded.location_id,
             trigger=excluded.trigger, priority=excluded.priority, repeatable=excluded.repeatable;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_bagageiro.forcar','vs_bagageiro','Forçar a porta com as mãos',10,'{}','{"text":"Você apoia o pé na fuselagem e puxa.","check":{"attr":"forca","base":45},"success":{"text":"O metal cede com um estalo. Você puxa a bateria (pesada!), uma jaqueta impermeável e um kit de primeiros socorros.","effects":[{"op":"flag","key":"bagageiro_aberto"},{"op":"addItem","item":"bateria_emergencia"},{"op":"addItem","item":"jaqueta"},{"op":"addItem","item":"atadura"},{"op":"addItem","item":"antisseptico"}]},"failure":{"text":"A porta não se move. Seu ombro estala de um jeito ruim.","effects":[{"op":"wound","part":"braco_dir","type":"entorse","severity":1}]}}',0,0)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_bagageiro.alavanca','vs_bagageiro','Usar um pedaço de metal como alavanca',15,'{}','{"text":"Você encaixa uma haste de alumínio da asa na fresta.","check":{"attr":"improviso","base":50,"itemBonus":{"canivete":15}},"success":{"text":"Com paciência, a trava cede. Bateria, jaqueta e um kit de primeiros socorros.","effects":[{"op":"flag","key":"bagageiro_aberto"},{"op":"addItem","item":"bateria_emergencia"},{"op":"addItem","item":"jaqueta"},{"op":"addItem","item":"atadura"},{"op":"addItem","item":"antisseptico"}]},"failure":{"text":"A haste entorta. Você perde tempo e fôlego.","effects":[{"op":"status","field":"energy","delta":-8}]}}',0,1)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_bagageiro.depois','vs_bagageiro','Deixar para depois',1,'{}','{"text":"Você se afasta do bagageiro. Ele não vai a lugar nenhum."}',1,2)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO events(id,scenario_id,title,body,location_id,trigger,priority,repeatable) VALUES('vs_vozes','vale_silente','Alguém chama seu nome','[whispers] Entre os troncos, uma voz chama o seu nome. [pause] [ominous] O nome completo, pronunciado devagar, como quem lê de um documento.','mata','{"night":true}',40,0)
           ON CONFLICT(id) DO UPDATE SET title=excluded.title, body=excluded.body, location_id=excluded.location_id,
             trigger=excluded.trigger, priority=excluded.priority, repeatable=excluded.repeatable;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_vozes.seguir','vs_vozes','Seguir a voz',30,'{}','{"text":"Você segue o som, desviando de raízes.","check":{"attr":"controle_emocional","base":45},"success":{"text":"A voz para. Numa árvore marcada com tinta laranja, pendurada num galho: a jaqueta de um uniforme de piloto. No bolso, um caderno de voo.","effects":[{"op":"addItem","item":"caderno_piloto"},{"op":"clue","key":"caderno_piloto"}]},"failure":{"text":"A voz parece mudar de lugar. Quando você enfim para, não reconhece mais nada. Leva quase uma hora para achar o caminho de volta — e você cai duas vezes.","effects":[{"op":"time","minutes":45},{"op":"status","field":"stress","delta":20},{"op":"wound","part":"perna_esq","type":"contusao","severity":1}]}}',0,0)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_vozes.ignorar','vs_vozes','Ignorar e seguir em frente',2,'{}','{"text":"Você não para. A voz não insiste. Isso é pior.","effects":[{"op":"status","field":"stress","delta":10}]}',1,1)
             ON CONFLICT(id) DO UPDATE SET label=excluded.label, duration_minutes=excluded.duration_minutes,
               requirements=excluded.requirements, outcome=excluded.outcome, safe=excluded.safe, sort_order=excluded.sort_order;

INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_vozes.observar','vs_vozes','Apagar a luz e observar em silêncio',15,'{}','{"text":"Você se agacha atrás de uma raiz e prende a respiração.","check":{"attr":"furtividade","base":50},"success":{"text":"Um facho de lanterna se move entre as árvores, subindo pela crista norte. Quem quer que seja, não está perdido: anda como quem conhece o caminho até a antena.","effects":[{"op":"clue","key":"luz_na_crista"},{"op":"revealLink","from":"trilha","to":"estacao"}]},"failure":{"text":"Você não vê nada. Mas escuta passos se afastando, sem pressa.","effects":[{"op":"status","field":"stress","delta":10}]}}',0,2)
