INSERT INTO events(id,scenario_id,title,body,location_id,trigger,priority,repeatable) VALUES('vs_estacao_interior','vale_silente','Dentro da estação','[tense] Cheiro de querosene e remédio. Uma cama de campanha desfeita, tiras de camisa sujas de sangue, um rádio de bancada antigo sem energia. Na parede, um mapa topográfico com alfinetes. Alguém esteve aqui há poucas horas.','estacao','{"flagsAll":["estacao_aberta"]}',44,0)
