INSERT INTO event_choices(id,event_id,label,duration_minutes,requirements,outcome,safe,sort_order) VALUES('vs_estacao_interior.esperar','vs_estacao_interior','Esconder-se e esperar quem voltar',60,'{}','{"text":"Você se encolhe atrás de um armário e espera.","check":{"attr":"furtividade","base":55},"success":{"text":"Um homem mancando entra, com uniforme de piloto rasgado e uma chave de roda na mão. Ele não vê você.","effects":[{"op":"flag","key":"piloto_presente"},{"op":"clue","key":"piloto_vivo"}]},"failure":{"text":"Ninguém entra. Mas quando você sai, a porta dos fundos está aberta — e não foi você quem abriu.","effects":[{"op":"flag","key":"piloto_presente"},{"op":"status","field":"stress","delta":15}]}}',1,2)
